INSERT INTO t_text_index_dense_postings
SELECT concat(
    if(cityHash64(number, 1) % 4 != 0, 'the ', ''),
    if(cityHash64(number, 2) % 2 = 0, 'and ', ''),
    if(cityHash64(number, 3) % 50 = 0, 'rare ', ''),
    'w', toString(cityHash64(number, 4) % 100000))
FROM numbers_mt(50000000)
